import re

def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Empty or invalid duration string")

    matches = re.findall(r'(\d+)([hms])', s)
    reconstructed = "".join(f"{num}{unit}" for num, unit in matches)

    if not matches or reconstructed != s:
        raise ValueError("Invalid duration string")

    units = [u for _, u in matches]
    if len(units) != len(set(units)):
        raise ValueError("Invalid duration string: duplicate units")

    hours = minutes = seconds = 0
    for num, unit in matches:
        val = int(num)
        if unit == 'h':
            hours += val
        elif unit == 'm':
            minutes += val
        elif unit == 's':
            seconds += val

    return hours * 3600 + minutes * 60 + seconds
