import math

def compact(n: int) -> str:
    if n < 0:
        raise ValueError("Non-negative integer expected")
    if n < 1000:
        return str(n)

    def round_half_up(x):
        return math.floor(x * 10 + 0.5) / 10

    def format_val(v):
        s = f"{v:.1f}"
        if s.endswith('.0'):
            return s[:-2]
        return s.replace('.', ',')

    units = [
        (1_000_000_000, 'bi'),
        (1_000_000, 'mi'),
        (1_000, 'mil')
    ]

    for scale, unit in units:
        if n < scale * 1000:
            val = n / scale
            rounded = round_half_up(val)
            if 1 <= rounded < 1000:
                return f"{format_val(rounded)} {unit}"

    # Fallback for very large numbers beyond specified units, extending pattern if needed
    # But per spec, we stop at bi. Handle arbitrarily large by scaling up generically:
    power = 3
    while n >= 1000 ** (power + 1):
        power += 1

    val = n / (1000 ** power)
    rounded = round_half_up(val)

    if power == 3: return f"{format_val(rounded)} mil"
    if power == 6: return f"{format_val(rounded)} mi"
    if power == 9: return f"{format_val(rounded)} bi"

    # Generic suffix for beyond billion if needed (not explicitly requested but safe)
    suffix = 'bi' if power == 9 else str(power)
    return f"{format_val(rounded)} {suffix}"
