from datetime import date, timedelta

def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    def is_bd(dt: date) -> bool:
        return dt.weekday() < 5 and dt not in holidays

    if n == 0:
        if is_bd(d):
            return d
        step = 1
        while not is_bd(d):
            d += timedelta(days=step)
        return d

    step = 1 if n > 0 else -1
    while n != 0:
        d += timedelta(days=step)
        if is_bd(d):
            n -= step
    return d
