def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(True)
    section_found = False
    key_found = False
    result_lines = []
    current_section = None

    for line in lines:
        stripped = line.strip()

        if stripped.startswith('[') and stripped.endswith(']'):
            sect_name = stripped[1:-1].strip()
            if sect_name == section:
                current_section = section
                section_found = True
            else:
                current_section = None

        if current_section == section:
            if '=' in stripped and not stripped.startswith('#') and not stripped.startswith(';'):
                potential_key, _, _ = stripped.partition('=')
                if potential_key.strip() == key:
                    # Preserve original line ending
                    ending = line[len(line.rstrip()):]
                    result_lines.append(f"{key} = {value}{ending}")
                    key_found = True
                    continue

        result_lines.append(line)

    if not section_found:
        raise KeyError(section)
    if not key_found:
        raise KeyError(key)

    return ''.join(result_lines)
