from decimal import Decimal, ROUND_HALF_UP

def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    thresholds = [1_000_000_000, 1_000_000, 1_000]
    units = ['bi', 'mi', 'mil']

    divisor = 1000
    unit = 'mil'
    for t, u in zip(thresholds, units):
        if n >= t:
            divisor = t
            unit = u
            break

    val = Decimal(str(n)) / Decimal(str(divisor))
    val_rounded = val.quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)

    while val_rounded >= 1000:
        idx = units.index(unit) + 1
        if idx < len(units):
            divisor = thresholds[idx]
            unit = units[idx]
            val = Decimal(str(n)) / Decimal(str(divisor))
            val_rounded = val.quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)
        else:
            break

    formatted = str(val_rounded).replace('.', ',')
    if formatted.endswith(',0'):
        formatted = formatted[:-2]

    return formatted
