import re
from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    is_negative = False
    if s.startswith('(') and s.endswith(')'):
        is_negative = True
        s = s[1:-1].strip()
    elif s.startswith('-'):
        is_negative = True
        s = s[1:].strip()

    s = re.sub(r'^\s*R\$\s*', '', s)

    if ',' in s:
        int_part_str, dec_part_str = s.rsplit(',', 1)
        if not dec_part_str.isdigit() or len(dec_part_str) != 2:
            raise ValueError("Invalid decimal part")
    else:
        int_part_str = s
        dec_part_str = '00'

    # Validate integer part format: plain digits or .-grouped in threes
    if '.' in int_part_str:
        if not re.fullmatch(r'\d{1,3}(?:\.\d{3})*', int_part_str):
            raise ValueError("Invalid integer part grouping")
        int_part_str = int_part_str.replace('.', '')

    if not int_part_str.isdigit() and len(int_part_str) > 0:
        raise ValueError("Invalid characters in integer part")

    if not int_part_str:
        int_part_str = '0'

    return (-1 if is_negative else 1) * Decimal(f"{int_part_str}.{dec_part_str}")
