import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    all_nodes = set(deps.keys())
    for dep_list in deps.values():
        all_nodes.update(dep_list)

    in_degree = {node: 0 for node in all_nodes}
    rev_adj = {node: [] for node in all_nodes}

    for item, dep_list in deps.items():
        for dep in dep_list:
            rev_adj[dep].append(item)
            in_degree[item] += 1

    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in rev_adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
