        if not current_line:
            current_line.append(chunk)
            current_len = cl
        elif current_len + 1 + cl <= width:
            current_line.append(chunk)
            current_len += 1 + cl
        else:
            lines.append(" ".join(current_line))
            current_line = [chunk]
            current_len = cl

    if current_line:
        lines.append(" ".join(current_line))

