            o_val = override[key]
            b_val = base.get(key)
            if isinstance(o_val, dict) and isinstance(b_val, dict):
                result[key] = deep_merge(b_val, o_val)
            else:
                result[key] = copy.deepcopy(o_val) if isinstance(o_val, (dict, list)) else o_val
        elif key in base:
            b_val = base[key]
            result[key] = copy.deepcopy(b_val) if isinstance(b_val, (dict, list)) else b_val
    return result
